#include "beva/physics.h"
#include <stdlib.h>
#include <math.h>
beva_status beva_nbody_step(const beva_particle*p,double*x,double*v,const beva_nbody_options*o){if(!p||!x||!v||!o)return BEVA_ERR_NULL;double*a=calloc(3*o->n,sizeof(double));if(!a)return BEVA_ERR_ALLOC;double e=o->softening>0?o->softening:1e-9;for(size_t i=0;i<o->n;i++)for(size_t j=i+1;j<o->n;j++){double dx=x[3*j]-x[3*i],dy=x[3*j+1]-x[3*i+1],dz=x[3*j+2]-x[3*i+2],r2=dx*dx+dy*dy+dz*dz+e*e,r=sqrt(r2),f=o->G/(r2*r);a[3*i]+=p[j].mass*f*dx;a[3*i+1]+=p[j].mass*f*dy;a[3*i+2]+=p[j].mass*f*dz;a[3*j]-=p[i].mass*f*dx;a[3*j+1]-=p[i].mass*f*dy;a[3*j+2]-=p[i].mass*f*dz;}for(size_t i=0;i<3*o->n;i+=3){v[i]+=o->dt*a[i];v[i+1]+=o->dt*a[i+1];v[i+2]+=o->dt*a[i+2];x[i]+=o->dt*v[i];x[i+1]+=o->dt*v[i+1];x[i+2]+=o->dt*v[i+2];}free(a);return BEVA_OK;}
beva_status beva_poisson_jacobi_2d(const double*f,size_t nx,size_t ny,double dx,double dy,size_t max,double tol,double*u,beva_solver_stats*s){if(!f||!u||nx<3||ny<3)return BEVA_ERR_INVALID;double*z=calloc(nx*ny,sizeof(double));if(!z)return BEVA_ERR_ALLOC;double ax=1/(dx*dx),ay=1/(dy*dy),d=2*(ax+ay),err=0;size_t it;for(it=0;it<max;it++){err=0;for(size_t i=1;i<nx-1;i++)for(size_t j=1;j<ny-1;j++){size_t q=i*ny+j;z[q]=((u[(i-1)*ny+j]+u[(i+1)*ny+j])*ax+(u[q-1]+u[q+1])*ay-f[q])/d;double x=fabs(z[q]-u[q]);if(x>err)err=x;}for(size_t i=1;i<nx-1;i++)for(size_t j=1;j<ny-1;j++)u[i*ny+j]=z[i*ny+j];if(err<tol)break;}free(z);if(s){s->iterations=it+1;s->residual=err;s->converged=err<tol;}return err<tol?BEVA_OK:BEVA_ERR_CONVERGENCE;}
beva_status beva_wave_1d_step(const double*a,const double*u,size_t n,double dt,double dx,double c,double*out){if(!a||!u||!out||n<3||dx==0)return BEVA_ERR_INVALID;double r=c*dt/dx;if(r*r>1)return BEVA_ERR_DOMAIN;for(size_t i=1;i<n-1;i++)out[i]=2*u[i]-a[i]+r*r*(u[i-1]-2*u[i]+u[i+1]);out[0]=out[n-1]=0;return BEVA_OK;}
beva_status beva_lorentz_gamma(double v,double c,double*g){if(!g||c<=0||fabs(v)>=c)return BEVA_ERR_DOMAIN;*g=1/sqrt(1-(v/c)*(v/c));return BEVA_OK;}
beva_status beva_schrodinger_dispersion(double k,double m,double h,double*e){if(!e||m<=0||h<=0)return BEVA_ERR_INVALID;*e=h*h*k*k/(2*m);return BEVA_OK;}
beva_status beva_kg_dispersion(double k,double m,double*w){if(!w||m<0)return BEVA_ERR_INVALID;*w=sqrt(k*k+m*m);return BEVA_OK;}
beva_status beva_dimensional_check(const int*a,const int*b,size_t n,int*out){if(!a||!b||!out)return BEVA_ERR_NULL;*out=1;for(size_t i=0;i<n;i++)if(a[i]!=b[i]){*out=0;break;}return BEVA_OK;}
